import heapq

def stable_toposort(graph):
    indegree = {node: 0 for node in graph}
    children = {node: [] for node in graph}

    for node, deps in graph.items():
        for dep in deps:
            if dep not in graph:
                raise ValueError(f"missing dependency: {dep!r}")
            indegree[node] += 1
            children[dep].append(node)

    rank = {node: i for i, node in enumerate(graph)}

    ready = []
    for node in graph:
        if indegree[node] == 0:
            heapq.heappush(ready, (rank[node], node))

    result = []
    while ready:
        _, node = heapq.heappop(ready)
        result.append(node)

        for child in children[node]:
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(ready, (rank[child], child))

    if len(result) != len(graph):
        raise ValueError("cycle detected")

    return result

