def schema_drift(expected, actual):
    drift = set()

    def add_paths(node, prefix):
        if isinstance(node, dict):
            if not node:
                drift.add(prefix)
                return
            for key, value in node.items():
                path = f"{prefix}.{key}" if prefix else key
                add_paths(value, path)
        else:
            drift.add(prefix)

    def compare(exp, act, prefix):
        if isinstance(exp, dict) and isinstance(act, dict):
            for key in set(exp) | set(act):
                path = f"{prefix}.{key}" if prefix else key
                if key not in exp:
                    add_paths(act[key], path)
                elif key not in act:
                    add_paths(exp[key], path)
                else:
                    compare(exp[key], act[key], path)
        elif isinstance(exp, dict) or isinstance(act, dict):
            drift.add(prefix)
        elif exp != act:
            drift.add(prefix)

    compare(expected, actual, "")
    return sorted(drift)
