def merge_payload_ranges(items):
    data = []
    for start, end, payload in items:
        if start > end:
            raise ValueError("start > end")
        data.append((start, end, payload))

    data.sort(key=lambda x: (x[0], x[1]))

    result = []
    last_by_payload = {}

    for start, end, payload in data:
        if payload in last_by_payload:
            idx = last_by_payload[payload]
            _, prev_end, _ = result[idx]

            can_merge = start <= prev_end
            if isinstance(start, int) and isinstance(prev_end, int):
                can_merge = start <= prev_end + 1

            if can_merge:
                if end > prev_end:
                    result[idx][1] = end
                continue

        result.append([start, end, payload])
        last_by_payload[payload] = len(result) - 1

    return result
